#include <stdlib.h>
#include <string.h>
#include <math.h>
typedef struct {double d; int j;} HE;
static void hpush(HE*h,int*n,double d,int j){int i=(*n)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static HE hpop(HE*h,int*n){HE top=h[0];HE x=h[--(*n)];int i=0,m=*n;for(;;){int c=2*i+1;if(c>=m)break;if(c+1<m&&h[c+1].d<h[c].d)c++;if(h[c].d>=x.d)break;h[i]=h[c];i=c;}h[i]=x;return top;}

/* select k smallest indices of arr (stride s) of length n into out */
static void ksmall(const double*M,int n,int base,int stride,int k,int*out){
  double bd[64];int cnt=0;
  for(int t=0;t<n;t++){double d=M[base+(long)t*stride];
    if(cnt<k){int p=cnt++;while(p>0&&bd[p-1]>d){bd[p]=bd[p-1];out[p]=out[p-1];p--;}bd[p]=d;out[p]=t;}
    else if(d<bd[k-1]){int p=k-1;while(p>0&&bd[p-1]>d){bd[p]=bd[p-1];out[p]=out[p-1];p--;}bd[p]=d;out[p]=t;}
  }
}
/* returns 0 ok, 1 infeasible, 2 not optimal */
static int solve_sparse(int n,const double*M,const int*ptr,const int*idx,int*col4row,double*u,double*v,
  int*row4col,double*spc,int*path,char*SC,int*scl,int*srl,HE*heap){
  for(int j=0;j<n;j++){v[j]=INFINITY;row4col[j]=-1;}
  for(int i=0;i<n;i++)for(int e=ptr[i];e<ptr[i+1];e++){int j=idx[e];double c=M[(long)i*n+j];if(c<v[j])v[j]=c;}
  for(int j=0;j<n;j++)if(!isfinite(v[j]))return 1;
  for(int i=0;i<n;i++){double m=INFINITY;int bj=-1;col4row[i]=-1;
    for(int e=ptr[i];e<ptr[i+1];e++){int j=idx[e];double r=M[(long)i*n+j]-v[j];if(r<m||(r==m&&row4col[j]<0&&bj>=0&&row4col[bj]>=0)){m=r;bj=j;}}
    u[i]=m; if(bj>=0&&row4col[bj]<0){row4col[bj]=i;col4row[i]=bj;}}
  for(int j=0;j<n;j++){spc[j]=INFINITY;SC[j]=0;}
  for(int cur=0;cur<n;cur++){ if(col4row[cur]>=0)continue;
    int hn=0,nsc=0,nsr=0,i=cur,sink=-1;double minv=0;
    srl[nsr++]=cur;
    int ntouched=0; /* use path as marker via spc */
    for(;;){
      for(int e=ptr[i];e<ptr[i+1];e++){int j=idx[e];if(SC[j])continue;
        double r=minv+M[(long)i*n+j]-u[i]-v[j];
        if(r<spc[j]){if(spc[j]==INFINITY)scl[n+ntouched++]=j;spc[j]=r;path[j]=i;hpush(heap,&hn,r,j);}}
      int j=-1;
      while(hn>0){HE t=hpop(heap,&hn);if(SC[t.j]||t.d>spc[t.j])continue;j=t.j;break;}
      if(j<0)return 1;
      minv=spc[j];SC[j]=1;scl[nsc++]=j;
      if(row4col[j]<0){sink=j;break;}
      i=row4col[j];srl[nsr++]=i;
    }
    u[cur]+=minv;
    for(int k=1;k<nsr;k++){int r=srl[k];u[r]+=minv-spc[col4row[r]];}
    for(int k=0;k<nsc;k++){int j=scl[k];v[j]-=minv-spc[j];}
    int j=sink;
    for(;;){int r=path[j];row4col[j]=r;int t=col4row[r];col4row[r]=j;if(r==cur)break;j=t;}
    for(int k=0;k<ntouched;k++){int jj=scl[n+k];spc[jj]=INFINITY;SC[jj]=0;}
  }
  return 0;
}
int lap(int n,const double*M,int k,int*col4row){
  int *ptr=malloc((n+1)*sizeof(int)),*cnt=calloc(n,sizeof(int));
  int *rk=malloc((long)n*64*sizeof(int)),*ck=malloc((long)n*64*sizeof(int));
  double*u=malloc(n*8),*v=malloc(n*8),*spc=malloc(n*8);
  int*row4col=malloc(n*4),*path=malloc(n*4),*scl=malloc(2*n*4),*srl=malloc(n*4);char*SC=malloc(n);
  int *idx=NULL; HE*heap=NULL;int ret=1;
  while(k<=48&&k<n){
    for(int i=0;i<n;i++)ksmall(M,n,i*n,1,k,rk+(long)i*k);
    for(int j=0;j<n;j++)ksmall(M,n,j,n,k,ck+(long)j*k);
    memset(cnt,0,n*4);
    for(int i=0;i<n;i++)cnt[i]+=k;
    for(int j=0;j<n;j++)for(int t=0;t<k;t++)cnt[ck[j*k+t]]++;
    ptr[0]=0;for(int i=0;i<n;i++)ptr[i+1]=ptr[i]+cnt[i];
    free(idx);idx=malloc(ptr[n]*4);free(heap);heap=malloc((ptr[n]+n)*sizeof(HE));
    memcpy(cnt,ptr,n*4);
    for(int i=0;i<n;i++)for(int t=0;t<k;t++)idx[cnt[i]++]=rk[i*k+t];
    for(int j=0;j<n;j++)for(int t=0;t<k;t++){int i=ck[j*k+t];idx[cnt[i]++]=j;}
    int r=solve_sparse(n,M,ptr,idx,col4row,u,v,row4col,spc,path,SC,scl,srl,heap);
    if(r==0){ /* verify */
      int ok=1;
      for(int i=0;i<n&&ok;i++){const double*Mi=M+(long)i*n;double ui=u[i];
        for(int j=0;j<n;j++)if(Mi[j]-ui-v[j]< -1e-12){ok=0;break;}}
      if(ok){ret=0;break;}
    }
    k*=2;
  }
  free(ptr);free(cnt);free(rk);free(ck);free(u);free(v);free(spc);free(row4col);free(path);free(scl);free(srl);free(SC);free(idx);free(heap);
  return ret;
}
