static void ksmall(const double*M,int n,long base,long stride,int k,int*out){
  double bd[64];int cnt=0;
  for(int t=0;t<n;t++){double d=M[base+(long)t*stride];
    if(cnt<k){int p=cnt++;while(p>0&&bd[p-1]>d){bd[p]=bd[p-1];out[p]=out[p-1];p--;}bd[p]=d;out[p]=t;}
