  }
}
/* adjacency: per row dynamic arrays */
typedef struct {int *a; int n, cap;} Vec;
static void vpush(Vec*v,int x){if(v->n==v->cap){v->cap=v->cap?v->cap*2:16;v->a=realloc(v->a,v->cap*4);}v->a[v->n++]=x;}

static int augment(int n,const double*M,Vec*adj,int*col4row,int*row4col,double*u,double*v,
  double*spc,int*path,char*SC,int*scl,int*srl,int*touched,HE*heap){
  for(int cur=0;cur<n;cur++){ if(col4row[cur]>=0)continue;
    int hn=0,nsc=0,nsr=0,i=cur,sink=-1,nt=0;double minv=0;
    srl[nsr++]=cur;
    for(;;){
      const int*id=adj[i].a;int ne=adj[i].n;const double*Mi=M+(long)i*n;double ui=u[i];
      for(int e=0;e<ne;e++){int j=id[e];if(SC[j])continue;
        double r=minv+Mi[j]-ui-v[j];
        if(r<spc[j]){if(spc[j]==INFINITY)touched[nt++]=j;spc[j]=r;path[j]=i;hpush(heap,&hn,r,j);}}
      int j=-1;
      while(hn>0){HE t=hpop(heap,&hn);if(SC[t.j]||t.d>spc[t.j])continue;j=t.j;break;}
      if(j<0)return 1;
      minv=spc[j];SC[j]=1;scl[nsc++]=j;
      if(row4col[j]<0){sink=j;break;}
      i=row4col[j];srl[nsr++]=i;
    }
    u[cur]+=minv;
    for(int k=1;k<nsr;k++){int r=srl[k];u[r]+=minv-spc[col4row[r]];}
    for(int k=0;k<nsc;k++){int j=scl[k];v[j]-=minv-spc[j];}
    int j=sink;
    for(;;){int r=path[j];row4col[j]=r;int t=col4row[r];col4row[r]=j;if(r==cur)break;j=t;}
    for(int k=0;k<nt;k++){int jj=touched[k];spc[jj]=INFINITY;SC[jj]=0;}
  }
  return 0;
}
int lap(int n,const double*M,int k,int*col4row){
  if(k>n)k=n;
  Vec*adj=calloc(n,sizeof(Vec));
  int *tmp=malloc((long)n*k*sizeof(int));
  double*u=malloc(n*8),*v=malloc(n*8),*spc=malloc(n*8);
  int*row4col=malloc(n*4),*path=malloc(n*4),*scl=malloc(n*4),*srl=malloc(n*4),*touched=malloc(n*4);
  char*SC=calloc(n,1);
  for(int i=0;i<n;i++){ksmall(M,n,(long)i*n,1,k,tmp);for(int t=0;t<k;t++)vpush(&adj[i],tmp[t]);}
  for(int j=0;j<n;j++){ksmall(M,n,j,n,k,tmp);for(int t=0;t<k;t++){int i=tmp[t];
     int dup=0;for(int e=0;e<k;e++)if(adj[i].a[e]==j){dup=1;break;} if(!dup)vpush(&adj[i],j);}}
  long tot=0;for(int i=0;i<n;i++)tot+=adj[i].n;
  long hcap=tot+n; HE*heap=malloc(hcap*sizeof(HE));
  /* init duals */
  for(int j=0;j<n;j++){v[j]=INFINITY;row4col[j]=-1;spc[j]=INFINITY;}
  for(int i=0;i<n;i++)for(int e=0;e<adj[i].n;e++){int j=adj[i].a[e];double c=M[(long)i*n+j];if(c<v[j])v[j]=c;}
  for(int i=0;i<n;i++){double m=INFINITY;int bj=-1;col4row[i]=-1;
    for(int e=0;e<adj[i].n;e++){int j=adj[i].a[e];double r=M[(long)i*n+j]-v[j];if(r<m){m=r;bj=j;}}
    u[i]=m; if(bj>=0&&row4col[bj]<0){row4col[bj]=i;col4row[i]=bj;}}
  int ret=1;
  for(int iter=0;iter<50;iter++){
    if(augment(n,M,adj,col4row,row4col,u,v,spc,path,SC,scl,srl,touched,heap)){ret=1;break;}
    int nviol=0;
    for(int i=0;i<n;i++){const double*Mi=M+(long)i*n;double ui=u[i];int bad=0;
      for(int j=0;j<n;j++)if(Mi[j]-ui-v[j]< -1e-12){vpush(&adj[i],j);bad=1;tot++;}
      if(bad){nviol++;int j=col4row[i];row4col[j]=-1;col4row[i]=-1;
        double m=INFINITY;for(int e=0;e<adj[i].n;e++){int jj=adj[i].a[e];double r=Mi[jj]-v[jj];if(r<m)m=r;}u[i]=m;}}
    if(nviol==0){ret=0;break;}
    if(tot+n>hcap){hcap=2*(tot+n);heap=realloc(heap,hcap*sizeof(HE));}
  }
  for(int i=0;i<n;i++)free(adj[i].a);
  free(adj);free(tmp);free(u);free(v);free(spc);free(row4col);free(path);free(scl);free(srl);free(touched);free(SC);free(heap);
  return ret;
}
